    "content": "中新网长春9月30日电 (谭伟旗 金乔)9月30日，《东北抗联创始人——罗登贤》新书发布会在吉林省近现代史展现场举行。新书填补相关研究空白，完善既有研究成果，完整还原罗登贤在东北早期抗日斗争中的开拓实践与奠基贡献。"
