    "description": "换其他镜像。注意被 TUNA 封禁的 IP，一般也会同时被 BFSU 镜像站封禁。 此外，您也可以尝试使用教育网联合镜像。它可以自动将您的请求转发给合适的镜像站。 MirrorZ Help Arch Linux 软件仓库 - MirrorZ Help Arch Linux 软件仓库 - 镜像使用帮助 - MirrorZ Help 致力于成为一个开源、开放、且持续更新的开源软件镜像的帮助文档整合站点，旨在帮助高校间推广开源软件的使用。",
