    "description": "中新网海口9月30日电 (张月和)茶叶、雪茄烟叶、野菜叶“三片叶”是海南五指山市的特色产业。五指山市农业农村和水务局局长李刚29日在海南省新闻办公室举行的“开局起步‘十五五’”系列主题新闻发布会五指山市专场上说，“十五五”时期，该市谋划做强“三片叶”，从种质提升、链条延伸、品牌赋能、联农增收四个方面协同发力，加快生态资源向富民产业高效转化。",
