    "description": "中新网漳州9月30日电 (彭莉芳)29日晚，由福建省文化和旅游厅主办，福建省闽台文化交流中心承办的“琴深诉说祖国情”——2026年闽台艺术青年音乐会，在福建省漳州市南靖县梅林镇官洋村云水谣景区举行，两岸音乐人同台献艺、共奏闽南乡音。省文旅系统相关部门负责人，海峡两岸的青年艺术家、音乐爱好者等近200人参加活动。",
