    "author": "胡喆",
    "description": "新华社北京9月30日电（记者胡喆）9月30日，中国科学院计算机网络信息中心在京发布磐石科研智能生态1.0，同步推出“磐石·壹科学”智能化科研平台与生态共建“薪火计划”，为我国“AI+科学”领域原始创新与成果转化提供新支撑。 中国科学院计算机网络信息中心主任周园春表示，此次发布是中国科学院落实国家人工智能发展规划的举措之一，依托全新生态体系推进智能化科研服务落地，助力人工智能与基础研究、前沿科研深度融合。 中国科学院计算机网络信息中心研究…",
    "content": "新华社北京9月30日电（记者胡喆）9月30日，中国科学院计算机网络信息中心在京发布磐石科研智能生态1.0，同步推出“磐石·壹科学”智能化科研平台与生态共建“薪火计划”，为我国“AI+科学”领域原始创新与成果转化提供新支撑。 中国科学院计算机网络信息中心主任周园春表示，此次发布是中国科学院落实国家人工智能发展规划的举措之一，依托全新生态体系推进智能化科研服务落地，助力人工智能与基础研究、前沿科研深度融合。 中国科学院计算机网络信息中心研究员杜一介绍，“磐石·壹科学”平台是该生态的核心载体，平台整合科研数据、模型与工具…"
