    "description": "明天就是假期。今早把公司的 Token 额度用完后，我坐在工位上发呆，忽然想到：再过不久，自己也要 30 岁了。 于是有些感慨，想写点东西，回顾步入社会以来的变化与想法。上一次有类似的冲动，还是大学刚毕业那会儿。随着年龄增长，分享欲一直在下降，还是抓住这次难得的冲动，写一写吧。 前言 两年多前，我读到一篇文章，印象很深：三十年，解决人生三大问题。 人生有三大难题：事业、家庭和财务。 第一个十年。你搞清楚自己想干什么，找到方向，为事业打下…",
