    "author": "杨湛菲,施钱贵",
    "description": "新华社北京9月30日电 题：画集里的长征史诗 新华社记者杨湛菲 青砖黛瓦，红迹寻踪。络绎不绝的参观者走进坐落于贵阳市中心的中共贵州省工委旧址，“万水千山只等闲——纪念中国工农红军长征胜利90周年专题展”正在这里展出。 展览开篇，《西行漫画》的书影吸引人们驻足细看。展板上介绍，作者黄镇曾是上海美专的学生，在长征途中担任红军宣传干部。他用捡来的纸片和锅底的灰，画下了山水、战友与百姓，这些战火中的素描，记录了一支军队的信念与意志。 1938年…",
    "content": "新华社北京9月30日电 题：画集里的长征史诗 新华社记者杨湛菲 青砖黛瓦，红迹寻踪。络绎不绝的参观者走进坐落于贵阳市中心的中共贵州省工委旧址，“万水千山只等闲——纪念中国工农红军长征胜利90周年专题展”正在这里展出。 展览开篇，《西行漫画》的书影吸引人们驻足细看。展板上介绍，作者黄镇曾是上海美专的学生，在长征途中担任红军宣传干部。他用捡来的纸片和锅底的灰，画下了山水、战友与百姓，这些战火中的素描，记录了一支军队的信念与意志。 1938年，作家阿英为初版《西行漫画》撰写题记：“在中国漫画中，请问有谁表现过这样伟大的内…"
