    "title": "[分享发现] 给客厅电视整了一个很有趣的控制应用",
    "link": "https://www.v2ex.com/t/1245875#reply1",
    "pub_date": "2026-09-30 17:37:41",
    "author": "wucc",
    "description": "客厅电视在我们家很重要，老的要刷肥皂剧，刚上小学的小朋友要看动画片 打游戏，我不愿意让小朋友看电视自带的首页节目，里面充斥着一些垃圾内容，前段时候都在看游戏直播视频，已经学会了主播一堆俚语了。 所以怎么解决呢？孩子每天上午 8 点上学 3 点多放学，我要在这个时间段开启电视自带主页，3 点之后就要屏蔽电视主页。朋友们看看我钻研了好几个晚上的方案： 1 ，电视是海信 E8Q pro ，首先开机广告可以让客服关闭，设置为默认进入上一次的输入…",
