    "pub_date": "2026-09-30 17:37:32",
    "author": "",
    "description": "据气象部门预报，未来三天，重庆、贵州部分地区有大到暴雨，上述地区近期持续阴雨天气，降雨重叠度高，山洪和地质灾害、中小河流洪水、城市内涝等风险较高。根据《国家防汛抗旱应急预案》及有关规定，国家防总、应急管理部决定于9月30日16时针对重庆、贵州启动防汛四级应急响应。",
    "content": "据气象部门预报，未来三天，重庆、贵州部分地区有大到暴雨，上述地区近期持续阴雨天气，降雨重叠度高，山洪和地质灾害、中小河流洪水、城市内涝等风险较高。根据《国家防汛抗旱应急预案》及有关规定，国家防总、应急管理部决定于9月30日16时针对重庆、贵州启动防汛四级应急响应。"
