    "content": "新华社福州9月30日电（记者周义）9月30日，福建电力现货市场正式运行，标志着福建以中长期市场为基础、现货市场为核心、辅助服务市场为配套的省内完整电力市场体系基本建成。 电力现货市场是电力市场化改革的核心环节，通过高频次的电能量交易，使电力商品价格动态反映供需关系和稀缺程度，是推动电力资源配置从计划控制向市场调节转变的关键路径。福建电力现货市场于2018年启动试运行，2025年3月进入连续结算试运行。 福建电力现货市场试运行以来，历经迎峰度夏、迎峰度冬、极端天气、重要节假日保电等各类场景的检验，整体运行平稳有序，有…"
