    "content": "新华社呼和浩特9月30日电（记者贺书琛）近日，能够实现从“储能”到“词元”的储算一体化创新项目在内蒙古自治区包头市开工建设。 项目通过电网侧储能电站与分布式智算中心耦合共建，创新构建算电动态运行机制，打通从绿色电力到词元规模化生产的增值链条，为算电协同深度发展探索新模式。 “十五五”规划纲要明确提出，推动绿色电力与算力协同布局。此次落地内蒙古的海博思创包头储算一体化项目暨词元工厂，在绿电直供等算电协同常规路径基础上，依托一体化能源算力底座，打通能源供给、储能调峰、算力调度全链条，拓展储能产业高价值应用场景。 一方面…"
