    "content": "新华社北京9月30日电 题:三大指数重返扩张区间 我国经济景气水平有所回升 新华社记者王雨萧 国家统计局服务业调查中心、中国物流与采购联合会30日发布数据显示，9月份，我国制造业采购经理指数（PMI）、非制造业商务活动指数和综合PMI产出指数分别为50.1%、50.2%和50.7%，重返扩张区间，经济景气水平有所回升。 记者注意到，制造业采购经理指数已连续两个月回升，9月份，在调查的21个行业中有12个行业PMI高于临界点，比上月增加4个，制造业行业景气面有所扩大。 “9月份，极端天气对经济的影响逐步消退，建筑业与…"
