    "pub_date": "2026-09-30 17:03:50",
    "author": "",
    "description": "中新网9月30日电 9月30日下午，国新办举行“开局起步‘十五五’”系列主题新闻发布会，介绍加快建设现代化水网有关情况。水利部部长李国英介绍称，1-9月，实施各类水利项目4.14万个，完成水利建设投资7950亿元，吸纳就业201万人。通过国家水网建设项目的加快实施和落地见效，为保障防洪安全、供水安全、粮食安全、生态安全提供有力支撑。",
    "content": "中新网9月30日电 9月30日下午，国新办举行“开局起步‘十五五’”系列主题新闻发布会，介绍加快建设现代化水网有关情况。水利部部长李国英介绍称，1-9月，实施各类水利项目4.14万个，完成水利建设投资7950亿元，吸纳就业201万人。通过国家水网建设项目的加快实施和落地见效，为保障防洪安全、供水安全、粮食安全、生态安全提供有力支撑。"
