    "content": "新华社北京9月30日电（记者朱高祥）民政部30日公布《民政事业发展“十五五”规划》，提出到“十五五”末，养老机构护理型床位占比达到73%、养老机构中取得职业技能等级证书的养老护理员占比达到65%、困难残疾人生活补贴和重度残疾人护理补贴覆盖率以及孤儿、事实无人抚养儿童基本生活保障覆盖率保持100%等多项发展指标。 规划提出，到2030年，各级民政部门党的建设全面加强，政策制度体系、服务保障体系、监督管理体系、社会参与体系进一步健全完善，老龄和养老服务、社会救助、社会福利、社会事务、社会治理工作水平进一步提升，民政事业…"
